'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/sheet/md-gb-bottom-sheet.js';
import '@material/web/labs/gb/components/sheet/md-gb-side-sheet.js';
import {BottomSheetElement} from '@material/web/labs/gb/components/sheet/bottom-sheet-element.js';
import {SideSheetElement} from '@material/web/labs/gb/components/sheet/side-sheet-element.js';

/**
 * A Material Design bottom sheet. Wraps <md-gb-bottom-sheet>.
 * Docs: https://material-web.dev/3.0/components/sheets/
 */
export const MdBottomSheet = createComponent({
  react: React,
  tagName: 'md-gb-bottom-sheet',
  elementClass: BottomSheetElement,
  events: {
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
    onStateChange: 'state-change' as EventName<Event>,
  },
});

export type MdBottomSheetProps = React.ComponentProps<typeof MdBottomSheet>;

/**
 * A Material Design side sheet. Wraps <md-gb-side-sheet>.
 * Docs: https://material-web.dev/3.0/components/sheets/
 */
export const MdSideSheet = createComponent({
  react: React,
  tagName: 'md-gb-side-sheet',
  elementClass: SideSheetElement,
  events: {
    onBack: 'back' as EventName<Event>,
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
  },
});

export type MdSideSheetProps = React.ComponentProps<typeof MdSideSheet>;
